					<text class="service-title">急诊陪同</text>
					<text class="service-desc">紧急情况 快速响应</text>
				</view>
				<view class="service-item" :class="{ 'selected': selectedService === 'home' }" @click="selectService('home')">
					<image class="service-icon" src="/static/logo_4.jpg" mode="aspectFit"></image>
					<text class="service-title">上门陪诊</text>
					<text class="service-desc">专门专业陪诊师 贴心陪伴</text>
				</view>
			</view>
		</view>
		
		<!-- 服务详情 -->
		<view class="service-details">
			<template v-if="selectedService">
				<text class="details-title">{{ serviceDetails[selectedService].title }}</text>
				<view class="detail-item" v-for="(detail, index) in serviceDetails[selectedService].details" :key="index">
					<image class="detail-icon" :src="detail.icon" mode="aspectFit"></image>
					<text class="detail-text">{{ detail.text }}</text>
				</view>
			</template>
			<template v-else>
				<text class="details-title">请选择服务类型</text>
				<view class="detail-item">
					<text class="detail-text">请先选择上方的服务类型以查看详细信息</text>
				</view>
			</template>
		</view>
		
		<!-- 推荐陪诊员 -->
		<view class="recommended-section">
			<text class="section-title">推荐陪诊员</text>
			<view class="companion-list">
				<view class="companion-card" :class="{ 'selected': selectedCompanion && selectedCompanion.id === companion.id }" v-for="(companion, index) in companions" :key="index" @click="selectCompanion(companion)">
					<image class="companion-avatar" :src="companion.avatar" mode="aspectFill"></image>
					<view class="companion-info">
						<text class="companion-name">{{ companion.name }}</text>
						<view class="companion-rating">
							<text class="rating-star">★</text>
							<text class="rating-score">{{ companion.rating }}</text>
							<text class="rating-count">({{ companion.reviewCount }})</text>
							<text class="experience">{{ companion.experience }}</text>
						</view>
						<view class="companion-tags">
							<text class="tag" v-for="(tag, tagIndex) in companion.tags" :key="tagIndex">{{ tag }}</text>
